SKIP = {"node_modules", ".git", "site-packages", "AppData", "__pycache__", "$Recycle.Bin", "Windows", ".venv", "venv"}


def is_app_folder(path):
    return os.path.isfile(os.path.join(path, "main.py")) and os.path.isfile(os.path.join(path, "routers", "users.py"))


def find_app_folders(root):
    for folder, dirs, _files in os.walk(root):
        dirs[:] = [d for d in dirs if d not in SKIP]
        if is_app_folder(folder):
            yield folder
            dirs[:] = []                      # nothing useful inside a backend folder


def install(app):
    changed = 0
    for rel, b64 in FILES.items():
        new = base64.b64decode("".join(b64))
        path = os.path.join(app, *rel.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        old = None
        if os.path.exists(path):
            with open(path, "rb") as fh:
                old = fh.read()
            if old.replace(b"\r\n", b"\n") == new:
                continue
            with open(path + ".bak", "wb") as fh:
                fh.write(old)
        with open(path, "wb") as fh:
            fh.write(new)
        changed += 1
        print("   updated", rel)
    print("   ->", changed, "file(s) updated," , len(FILES) - changed, "already current")


def main():
    target = sys.argv[1] if len(sys.argv) > 1 else os.path.expanduser("~")
    if is_app_folder(target):
        apps = [target]
    else:
        print("Searching", target, "for the backend ...")
        apps = list(find_app_folders(target))
    if not apps:
        print("Could not find the backend. Run again with the folder that contains main.py, e.g.:")
        print('   python install_manage_users.py "C:\\Users\\GK\\Downloads\\expense_tracker_backend\\expense_tracker_backend\\app"')
        return
    for app in apps:
        print("Backend:", app)
        install(app)

    print()
    s = socket.socket()
    s.settimeout(1)
    busy = s.connect_ex(("127.0.0.1", 8000)) == 0
    s.close()
    if busy:
        print("The OLD backend is still running on port 8000. Close it first:")
        try:
            out = subprocess.run(["netstat", "-ano"], capture_output=True, text=True).stdout
            for line in out.splitlines():
                if ":8000" in line and "LISTENING" in line:
                    pid = line.split()[-1]
                    print("  taskkill /PID", pid, "/F")
        except OSError:
            pass
    else:
        print("Port 8000 is free.")
    print("Then start the backend from its app folder:   python -m uvicorn main:app")
    print("It must print:  [bills] duplicate bills are checked inside one expense only")


if __name__ == "__main__":
    main()